// ============================================================
// CONFIGURE
// ============================================================
const BOT_NAME = 'Support Bot';           // Display name in Cliq
const SYSTEM_PROMPT = `You are a helpful internal support bot. 
Answer questions about company processes, IT issues, and general queries.
Keep responses concise and actionable. If you don't know, say so.
Do not make up information.`;

const MAX_HISTORY = 10; // Max conversation turns to keep in context
// ============================================================

const body = $input.first().json.body || $input.first().json;

// Cliq sends different event types
const eventType = body.type || body.event_type || 'message';
const userMessage = body.message || body.text || '';
const userName = body.name || body.sender?.name || 'User';
const chatId = body.chat?.id || body.access_token || 'default';

if (!userMessage || userMessage.trim() === '') {
  return [{
    json: {
      skip: true,
      response: { text: 'Hello! How can I help you today?' },
      botName: BOT_NAME
    }
  }];
}

// Simple conversation memory via Static Data
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
if (!staticData.conversations[chatId]) staticData.conversations[chatId] = [];

const history = staticData.conversations[chatId];
history.push({ role: 'user', content: `${userName}: ${userMessage}` });

// Trim history
while (history.length > MAX_HISTORY * 2) {
  history.shift();
}

// Build messages array for OpenAI
const messages = [
  { role: 'system', content: SYSTEM_PROMPT },
  ...history
];

return [{
  json: {
    chatId,
    messages,
    botName: BOT_NAME,
    userName,
    userMessage
  }
}];

// Format the AI response for Cliq and save to conversation history
const prev = $('Process Cliq Message').first().json;
const aiResponse = $input.first().json;

let reply = 'Sorry, I encountered an error processing your request.';

try {
  reply = aiResponse.choices[0].message.content;
} catch (e) {
  // Keep default error message
}

// Save assistant reply to history
const staticData = $getWorkflowStaticData('global');
if (staticData.conversations && staticData.conversations[prev.chatId]) {
  staticData.conversations[prev.chatId].push({ role: 'assistant', content: reply });
}

// Clean up old conversations (older than 1 hour of inactivity)
const now = Date.now();
if (!staticData.lastCleanup || now - staticData.lastCleanup > 3600000) {
  staticData.lastCleanup = now;
  // Simple cleanup: if too many conversations, clear oldest half
  const keys = Object.keys(staticData.conversations || {});
  if (keys.length > 100) {
    keys.slice(0, 50).forEach(k => delete staticData.conversations[k]);
  }
}

// Return Cliq-formatted response
// This is the webhook response body that Cliq expects
return [{
  json: {
    text: reply,
    bot: {
      name: prev.botName
    }
  }
}];
